"""Page summaries cover the entire page. Exercise pages contain guidance, answers follow."""
SUMMARIES={
'as-01-01':['按寄存器、内存、运算、分支、循环和调用逐步学习。','代码采用8086实模式与NASM的Intel写法。','左下查看完整运行结果，右侧执行卡查看中间状态。','每章一题，讲完留4秒思考，再查看答案。'],
'as-01-02':['MOV AX,3把立即数3写入AX。','ADD AX,5读取AX中的3，加5后写回8。','Intel写法通常左侧是目标，右侧是来源。','执行过程按读取、计算、写回三个动作追踪。'],
'as-01-03':['1字节是8位；8086的1个字是16位。','1位十六进制对应4位二进制，H是数制后缀。','8位FFh：无符号值255，补码有符号值−1。','8位范围：无符号0～255，有符号−128～127。'],
'as-01-04':['AX为16位，AH是高8位，AL是低8位。','AX=1234h时，AH=12h，AL=34h。','MOV AL,56h更新低8位，AH保持12h。','本例最终AX=1256h；AH、AL共同组成AX。'],
'as-01-05':['内存按字节编址，连续两个地址相差1。','1个16位字占连续2字节，小端先放低字节。','把1234h写到0200h：0200h放34h，0201h放12h。','按字读回重新组合为1234h，BX接收这个值。'],
'as-01-06':['实模式物理地址＝段值×16＋有效偏移。','1234h×16＋0010h＝12350h。','CS:IP定位指令；普通数据常用DS；栈用SS:SP。','计算地址时，先选段，再算偏移，最后相加。'],
'as-01-07':['给定AX=1234h，本次只向AL写入ABh。','先把AX拆成AH、AL两部分，更新对应8位。','再按小端规则，把完整AX写到0200h起的两格。','答案需同时给出AX、0200h字节和0201h字节。'],
'as-01-08':['AH保留12h，AL改为ABh，所以AX=12ABh。','小端存放时，低字节ABh进入0200h。','高字节12h进入下一地址0201h。','先核对修改范围，再核对两个字节的存放顺序。'],
'as-02-01':['MOV复制来源的位，来源继续保存原值。','先令AX=7并复制给BX，AX与BX都为7。','再令AX=9，最终AX=9、BX=7。','两侧位宽匹配；内存间复制可经寄存器中转。'],
'as-02-02':['0200h是地址数值，[0200h]表示按地址访问内存。','本例BX=0200h；该处34h、12h按字读成1234h。','MOV AX,[BX]读取数据，BX保持0200h。','再写到0202h起：0202h为34h，0203h为12h。'],
'as-02-03':['BX=0200h、SI=4时，BX+SI+2=0206h。','LEA DX,[BX+SI+2]让DX取得有效偏移0206h。','MOV AX,[BX+SI+2]按该地址读取一个字。','给定字节78h、56h，读入AX的值为5678h。'],
'as-02-04':['16位单寄存器寻址常用BX、BP、SI、DI。','双寄存器可用BX/BP搭配SI/DI，再加位移。','普通含BP寻址默认SS；常见BX/SI/DI寻址默认DS。','段值与偏移一起算物理位置，段超越可明确指定段。'],
'as-02-05':['DB按字节安排数据，DW按16位字安排数据。','EQU定义汇编期常量，标签标记数据位置。','BYTE写1字节：原CDh、ABh变为01h、ABh。','WORD写2字节：原CDh、ABh变为01h、00h。'],
'as-02-06':['给定0200h=78h，0201h=56h，DS已设置。','MOV BX,0200h先让BX保存地址数值。','再按[BX]读取一个16位字，使用两个字节。','分别写出地址寄存器BX与数据寄存器AX的结果。'],
'as-02-07':['BX保存0200h，负责定位内存。','AX按小端读取78h、56h，组合成5678h。','读完后，BX继续保持0200h。','原内存字节保持，读取动作把副本交给AX。'],
'as-03-01':['ADD相加、SUB相减，结果写回左侧目标。','AX先为10，SUB AX,10后AX=0、ZF=1。','再ADD AX,1，AX=1、ZF=0。','数值放在目标寄存器，条件标志另行保存。'],
'as-03-02':['8位FFh+1：低8位为00h，CF=1、OF=0。','8位7Fh+1：低8位为80h，CF=0、OF=1。','CF记录无符号进位，OF判断有符号范围。','先标位宽与数值解释，再读取相应溢出标志。'],
'as-03-03':['INC加1、DEC减1，同时保留原CF。','STC后让FFh递增：AL=00h，CF仍为1。','多字相加先对低字ADD，再对高字ADC。','FFFFh+1得到DX:AX=0001:0000h。'],
'as-03-04':['8位MUL计算AL×来源，完整16位积放入AX。','20×15=300，MUL后AX=012Ch。','8位IMUL按有符号解释；−5×3=−15，AX=FFF1h。','16位乘法使用AX，完整积放在DX:AX。'],
'as-03-05':['8位DIV：AX给出被除数，来源给出除数。','1000÷30：商33到AL，余数10到AH。','16位DIV使用DX:AX，商到AX、余数到DX。','无符号先准备高半部；有符号用CBW/CWD扩展。'],
'as-03-06':['给定AL=7Fh，执行ADD AL,1，保留8位。','先写完整和，再确定低8位保留的位串。','CF按无符号进位判断，OF按有符号范围判断。','答案分别列AL、CF、OF，并说明数值解释。'],
'as-03-07':['保留结果AL=80h，CF=0，OF=1。','无符号127+1=128，在8位范围内。','有符号正128超出最大值127，因此OF=1。','80h按8位补码读成−128，与位串结果对应。'],
'as-04-01':['AND同位全1才1；OR至少一个1；XOR相异为1。','1010与1100：AND=1000，OR=1110，XOR=0110。','寄存器与自身XOR可清零，并形成相应标志。','NOT逐位取反，条件标志保持原值。'],
'as-04-02':['AND掩码用于保留位，OR置1，XOR翻转指定位。','ABh AND 0Fh＝0Bh，保留低4位。','0Bh OR 80h＝8Bh，最高位置1。','8Bh XOR 1＝8Ah，翻转最低位。'],
'as-04-03':['TEST按AND形成标志，目标数据保持原值。','AL=81h，TEST AL,1后AL仍为81h、ZF=0。','CMP按相减形成标志，目标保留原数值。','再CMP AL,81h，相等使ZF=1，AL仍为81h。'],
'as-04-04':['SHL左移右补0，SHR右移左补0。','SAR右移时，左侧复制原来的符号位。','80h右移1位：SHR得40h，SAR得C0h。','8086次数用1或CL；移出位按规则进入CF。'],
'as-04-05':['ROL向左循环，ROR向右循环，移出位回到另一端。','81h执行ROR 1后为C0h，CF记录移出的一。','RCL/RCR把原CF也作为循环的一部分。','带进位循环先记录旧CF，再追踪各位的新位置。'],
'as-04-06':['给定AL=81h，顺序执行TEST AL,1与SHR AL,1。','先记录TEST之后保留下来的AL。','再画逻辑右移：最高位补0，最低位移出。','最后分别写移位后的AL和CF。'],
'as-04-07':['TEST后AL继续保存81h。','SHR右移1位后，AL=40h。','原最低位的一移出，CF=1。','检查与修改分开记录，按执行顺序更新状态。'],
'as-05-01':['标签给代码位置起名字，JMP直接转到目标。','CMP形成ZF，JE/JZ在ZF=1时跳转。','本例比较5与5，进入SAME并把BX写为1。','两条路径在DONE汇合，按选中的路径更新结果。'],
'as-05-02':['无符号比较：JA大于、JB小于，JAE/JBE含相等。','CMP左侧减右侧，跳转关系按这个顺序解释。','FFh按8位无符号是255，所以与1比较时JA成立。','严格大于对应CF=0且ZF=0；相等时ZF=1。'],
'as-05-03':['有符号比较使用JG、JL、JGE、JLE。','FFh按8位补码是−1，所以与1比较时JL成立。','有符号小于的条件是SF与OF相异。','用数值关系与标志条件互相回查比较结果。'],
'as-05-04':['AX保存候选，BX保存另一个无符号数。','CMP AX,BX后，JAE成立就保留AX。','BX更大时，MOV AX,BX完成候选更新。','7与12最终取12；15与12取15；相等时保留原值。'],
'as-05-05':['CMP AX,5先得到相等状态，ZF=1。','INC BX把BX从0变1，同时使ZF变为0。','随后的JE读取当前ZF，因此顺序执行。','本例最终BX=1、DX=9；追踪ZF的最近写入。'],
'as-05-06':['给定AL=FFh，执行CMP AL,1。','先把FFh分别解释为8位无符号数和补码数。','按各自关系判断JA与JL是否成立。','答案写出两种判断，以及对应的数值解释。'],
'as-05-07':['无符号FFh=255，大于1，JA成立。','有符号FFh=−1，小于1，JL成立。','同一比较形成一组标志，跳转采用各自解释规则。','按数据用途选择无符号或有符号条件。'],
'as-06-01':['LOOP先让CX减1，结果非0就回到标签。','本例CX初始3，每轮AX加2。','AX逐轮为2、4、6，CX逐轮为2、1、0。','初始化位于回跳目标之前，最后AX=6、CX=0。'],
'as-06-02':['直接进入循环体且CX=0时，LOOP会减成FFFFh。','该16位计数结构会执行65536轮。','允许零长度时，在循环体前使用JCXZ。','本例CX=0直接到DONE，AX保持0。'],
'as-06-03':['字节数组从0200h开始，元素是3、5、7。','SI定位、CX计数、AX累加，字节步长为1。','每轮字节读入BL，清BH后用BX参与16位加法。','最终AX=15、SI=0203h、CX=0。'],
'as-06-04':['每个16位元素占2字节，起点为0200h、0202h、0204h。','地址每轮加2，次数按元素个数给出。','100、200、300按字读取并累加，AX=600。','最终SI=0206h、CX=0；按最大总和选择位宽。'],
'as-06-05':['MOVSB从DS:SI复制1字节到ES:DI。','CLD令DF=0，复制后SI与DI各递增1。','REP按CX重复，本例复制ABC三个字节。','最终目标为ABC，SI=0203h、DI=0303h、CX=0。'],
'as-06-06':['给定3个16位元素，从0200h开始逐项处理。','先用元素宽度确定指针每轮的字节步长。','再由轮数计算结束偏移。','最后写出CX=0时进入结束路径的检查指令。'],
'as-06-07':['每项2字节，所以指针每轮加2。','3轮共前进6字节，最终SI=0206h。','这个位置在数组末尾之后，表示处理结束。','零长度用循环体前的JCXZ直接转到DONE。'],
'as-07-01':['字PUSH先令SP减2，再写入SS:SP。','字POP先读取当前栈顶，再令SP加2。','先压1234h再压ABCDh，弹出顺序为ABCDh、1234h。','本例两次压栈、两次出栈后，SP回到0100h。'],
'as-07-02':['同段近CALL把下一条IP压栈，再进入子程序。','近RET取回IP，执行接续到调用之后。','本例AX从4加到5，返回后复制到BX。','最终AX=5、BX=5；近CALL/RET的SP变化配对恢复。'],
'as-07-03':['本例约定AX传入数值，并用AX返回结果。','BX由子程序保护：使用前PUSH，结束前POP。','输入AX=4，临时用BX=3完成加法，返回AX=7。','BX恢复99，SP恢复，分别核对结果与保护项。'],
'as-07-04':['先压参数，近CALL压返回IP，再保存旧BP。','令BP=SP后，[BP]是旧BP，[BP+2]是返回IP。','本例[BP+4]读参数7，加1后AX返回8。','恢复BP并RET，调用者ADD SP,2清理参数。'],
'as-07-05':['栈顶临时字与返回IP按实际入栈顺序排列。','RET从当前栈顶取IP，栈顶内容决定返回位置。','正确过程先恢复临时保存项，再让RET取返回IP。','逐项核对PUSH/POP、SP、返回值和保护寄存器。'],
'as-07-06':['给定SP=0100h，AX=1234h，BX=ABCDh。','按PUSH AX、PUSH BX的顺序画两个字。','再按后入先出，把两个值分给DX与CX。','每次字操作按2字节计算，最后写出SP。'],
'as-07-07':['DX先取得ABCDh，CX再取得1234h。','SP轨迹：0100h→00FEh→00FCh→00FEh→0100h。','数值按后入先出分配，字操作每次改变SP两字节。','分析带CALL的栈表时，把返回IP也加入记录。'],
'as-08-01':['数值5是05h，字符5的ASCII码是35h。','合法单个数字加字符0，可得到对应字符码。','数字字符减字符0，可还原为0～9的数值。','本例最终AL=35h，BL=05h。'],
'as-08-02':['本章使用DOS INT 21h服务，AH选择功能。','单字符输出准备AH=02h，DL保存字符码。','本例DL放字符A，执行INT 21h后输出A。','工程以教学适配器记录服务调用与输出内容。'],
'as-08-03':['DOS 09h使用DS:DX定位字符串开头。','数据按字节读取，以$为结束标记。','0200h起的HI$显示为HI。','按长度、0结束、$结束分别依据接口约定准备。'],
'as-08-04':['DOS 01h读取并回显1字符，字符码返回AL。','先与字符0、9比较，按ASCII范围分类。','输入7通过范围检查，减字符0后BL=7。','输入A走BAD路径，BL=FFh作为本例标记。'],
'as-08-05':['123连续除10，商依次12、1、0。','余数依次3、2、1，按这个顺序压栈。','弹出为1、2、3，加字符0后逐字符输出。','16位DIV每轮先清DX；输入0也输出字符0。'],
'as-08-06':['AL当前保存数值7，先确定对应的字符编码转换。','再按单字符接口要求准备输出寄存器。','另一问使用DOS 09h，数据为HI$。','根据该服务的结束规则，写出实际显示内容。'],
'as-08-07':['数值7加ASCII字符0，得到字符7。','单字符输出按接口把字符码放入DL。','09h字符串服务显示HI，在$处结束。','编码转换与字符串范围分别按各自规则检查。'],
'as-09-01':['文件声明CPU 8086、BITS 16、ORG 100h。','ORG给汇编器提供起始偏移，标签据此计算。','程序先令DS=CS，再用09h服务输出OK。','最后AH=4Ch请求退出，AL=0给出正常返回码。'],
'as-09-02':['汇编列表并排显示源行、地址和机器码。','MOV AX,1234h的前三字节为B8 34 12。','IP按实际指令长度推进，修改后由重新汇编更新。','本例最终AX=BX=1235h。'],
'as-09-03':['单步表依次写执行前、当前指令、执行后。','例子AX=3，执行ADD AX,5后AX=8。','状态卡显示本步完成后的值，IP指向后续位置。','从首处预期与实际差异开始，沿路径继续定位。'],
'as-09-04':['汇编阶段查看操作数宽度、写法与寻址诊断。','执行阶段查看除法错误等异常现场。','结果阶段核对数据解释、跳转路径和任务输出。','分别用宽度冲突、除0和比较解释错误定位。'],
'as-09-05':['任务同时需要BX递增与按AX比较选择路径。','先INC BX，再CMP，让JE接着读取新比较结果。','本例BX从0到1；AX与5相等，ZF=1。','JE跳到EQUAL，最终BX=1，DX保持初始0。'],
'as-09-06':['MOV AX,BL：先比较两个操作数的宽度。','DIV除数为0：查看执行时的被除数与除数。','有符号任务使用无符号条件：核对解释与路径。','为每个现象选择汇编、执行或结果检查阶段。'],
'as-09-07':['AX为16位、BL为8位，传送宽度冲突由汇编诊断。','除数0触发指令执行阶段的除法错误。','比较解释与任务相异时，从跳转路径和结果定位。','分清错误阶段，再查看对应的直接证据。'],
'as-10-01':['输入为0200h起的3个无符号字节：3、5、7。','DX保存总和，BL保存候选最大值。','SI指向当前元素，CX保存剩余数量。','先清总和与候选，再设置起点和次数。'],
'as-10-02':['每轮字节读入AL，再清AH，形成无符号16位加数。','ADD DX,AX让总和留在DX。','输入3、5、7时，DX依次为3、8、15。','3个字节最大总和765，16位无符号范围足够。'],
'as-10-03':['CMP AL,BL比较当前元素与候选。','当前项≤候选时，JBE到KEEP；更大时更新BL。','原数组让候选逐项从0更新为3、5、7。','较小和相等输入走保留路径，再统一推进循环。'],
'as-10-04':['AX提供要显示的无符号数，print_u16负责转换。','先显示15，再输出空格，再显示7。','子程序用除10与栈把数值转成按序数字字符。','最终服务记录为15 7；计算与显示分别核对。'],
'as-10-05':['先确认模式、语法、初态、位宽与数值解释。','再算地址，按分支路径、循环轮次更新状态。','遇到调用配合栈表，最后检查结果、标志与SP。','学习新架构时，沿用追踪方法并核对具体规则。'],
'as-10-06':['给定3个无符号字节3、5、7，起点0200h。','每轮处理1字节，记录总和DX与候选BL。','同时记录SI的前进和CX的递减。','答案同时给出两项数据结果与两项循环终态。'],
'as-10-07':['总和DX=15，最大值BL=7。','SI从0200h前进3字节，最终为0203h。','CX递减到0，执行离开循环。','四项分别核对累加、候选更新、地址推进和退出。']}

def apply(chapters):
    seen=set()
    for c in chapters:
        for s in c['scenes']:
            notes=SUMMARIES[s['key']];assert len(notes)==4;s['summary']=notes
            for p in s['parts']:p['notes']=list(notes)
            seen.add(s['key'])
    assert seen==set(SUMMARIES)
